package controller.model;
import java.time.LocalDate; import java.time.LocalTime; import java.util.Optional;
import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import controller.model.repository.Appointment; import controller.model.repository.AppointmentRepository; import jakarta.servlet.http.HttpSession;
@Controller public class AppointmentController {
 private final AppointmentRepository appointments; public AppointmentController(AppointmentRepository a){appointments=a;}
 @GetMapping("/donation") public String page(HttpSession s,Model m){if(!logged(s))return "redirect:/login";m.addAttribute("admin",admin(s));m.addAttribute("appointment",new Appointment());m.addAttribute("appointments",admin(s)?appointments.findAllByOrderByAppointmentDateAscAppointmentTimeAsc():appointments.findByUserIdOrderByAppointmentDateAscAppointmentTimeAsc(uid(s)));add(s,m);return "donation";}
 @PostMapping("/donation") public String create(Appointment a,HttpSession s,RedirectAttributes f){if(!logged(s)||admin(s))return "redirect:/dashboard";if(a.getAppointmentDate()==null||a.getAppointmentDate().isBefore(LocalDate.now())||a.getAppointmentTime()==null){f.addFlashAttribute("error","Choose a future date and a time.");return "redirect:/donation";}a.setUserId(uid(s));a.setLocation(a.getLocation()==null||a.getLocation().isBlank()?"LifeLink Donation Center":a.getLocation());a.setStatus("UPCOMING");appointments.save(a);f.addFlashAttribute("success","Appointment scheduled.");return "redirect:/donation";}
 @PostMapping("/donation/{id}/reschedule") public String reschedule(@PathVariable Long id,@RequestParam LocalDate appointmentDate,@RequestParam LocalTime appointmentTime,HttpSession s,RedirectAttributes f){Optional<Appointment>a=appointments.findById(id);if(a.isEmpty()||(!admin(s)&&!a.get().getUserId().equals(uid(s))))return "redirect:/donation";if(appointmentDate.isBefore(LocalDate.now())){f.addFlashAttribute("error","Choose a future date.");return "redirect:/donation";}a.get().setAppointmentDate(appointmentDate);a.get().setAppointmentTime(appointmentTime);a.get().setStatus("UPCOMING");appointments.save(a.get());f.addFlashAttribute("success","Appointment rescheduled.");return "redirect:/donation";}
 @PostMapping("/donation/{id}/cancel") public String cancel(@PathVariable Long id,HttpSession s,RedirectAttributes f){Optional<Appointment>a=appointments.findById(id);if(a.isPresent()&&(admin(s)||a.get().getUserId().equals(uid(s)))){a.get().setStatus("CANCELLED");appointments.save(a.get());f.addFlashAttribute("success","Appointment cancelled.");}return "redirect:/donation";}
 @PostMapping("/donation/{id}/status") public String status(@PathVariable Long id,@RequestParam String status,HttpSession s){if(!admin(s))return "redirect:/dashboard";appointments.findById(id).ifPresent(a->{a.setStatus(status);appointments.save(a);});return "redirect:/donation";}
 private boolean logged(HttpSession s){return s.getAttribute("userId")!=null;}private boolean admin(HttpSession s){return "ADMIN".equalsIgnoreCase(String.valueOf(s.getAttribute("role")));}private Long uid(HttpSession s){return ((Number)s.getAttribute("userId")).longValue();}private void add(HttpSession s,Model m){m.addAttribute("firstName",s.getAttribute("firstName"));}
}
